import assert from 'node:assert/strict';
import { DatabaseSync } from 'node:sqlite';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Worker } from 'node:worker_threads';
import test from 'node:test';
import { migrate } from '../src/migrations.mjs';
import { createCheckoutService } from '../src/checkout.mjs';
import { migrations, seed } from '../src/schema.mjs';

function open() {
  const db = new DatabaseSync(':memory:');
  seed(db);
  migrate(db, migrations, 2);
  return db;
}

test('concurrent duplicate checkouts persist exactly one order and outbox event', async () => {
  const db = open();
  try {
    const checkout = createCheckoutService(db);
    const result = await Promise.all(Array.from({ length: 20 }, () => checkout({ key: 'retry-☕', sku: 'coffee', quantity: 2 })));
    assert.equal(new Set(result.map((item) => item.orderId)).size, 1);
    assert.ok(result.every((item) => item.totalCents === 2500));
    assert.equal(db.prepare('SELECT stock FROM products WHERE sku = ?').get('coffee').stock, 8);
    assert.equal(db.prepare('SELECT count(*) AS n FROM orders').get().n, 1);
    assert.equal(db.prepare('SELECT count(*) AS n FROM order_outbox').get().n, 1);
    await assert.rejects(checkout({ key: 'retry-☕', sku: 'tea', quantity: 2 }), /conflict/i);
    await assert.rejects(checkout({ key: 'retry-☕', sku: 'coffee', quantity: 3 }), /conflict/i);
    assert.equal(db.prepare('SELECT stock FROM products WHERE sku = ?').get('tea').stock, 5);
  } finally { db.close(); }
});

test('fault after debit rolls back stock and allows retry; invalid orders are rejected', async () => {
  const db = open();
  try {
    await assert.rejects(createCheckoutService(db, { afterDebit() { throw new Error('injected disk fault'); } })({ key: 'retry', sku: 'coffee', quantity: 3 }), /injected disk fault/);
    assert.equal(db.prepare('SELECT stock FROM products WHERE sku = ?').get('coffee').stock, 10);
    assert.equal(db.prepare('SELECT count(*) AS n FROM orders').get().n, 0);
    assert.equal(db.prepare('SELECT count(*) AS n FROM order_outbox').get().n, 0);
    const checkout = createCheckoutService(db);
    assert.equal((await checkout({ key: 'retry', sku: 'coffee', quantity: 3 })).totalCents, 3750);
    for (const request of [
      { key: 'large', sku: 'coffee', quantity: 100 }, { key: 'fraction', sku: 'coffee', quantity: 0.5 },
      { key: '', sku: 'coffee', quantity: 1 }, { key: 'negative', sku: 'coffee', quantity: -1 },
      { key: 'missing', sku: 'missing', quantity: 1 }
    ]) await assert.rejects(checkout(request));
    assert.equal(db.prepare('SELECT stock FROM products WHERE sku = ?').get('coffee').stock, 7);
  } finally { db.close(); }
});

test('independent SQLite connections serialize competing buyers without overselling', { timeout: 20000 }, async (t) => {
  const directory = await mkdtemp(join(tmpdir(), 'galaxy-buyers-'));
  t.after(() => rm(directory, { recursive: true, force: true }));
  const path = join(directory, 'orders.sqlite');
  const db = new DatabaseSync(path);
  try {
    seed(db);
    migrate(db, migrations, 2);
    const workerURL = new URL('./helpers/checkout-worker.mjs', import.meta.url);
    const outcomes = await Promise.all(Array.from({ length: 8 }, (_, index) => new Promise((resolve, reject) => {
      const worker = new Worker(workerURL, { workerData: { path, request: { key: 'buyer-' + index, sku: 'coffee', quantity: 2 } } });
      let message;
      worker.on('message', (value) => { message = value; });
      worker.on('error', reject);
      worker.on('exit', (code) => code === 0 && message ? resolve(message) : reject(new Error('Worker failed: ' + code)));
    })));
    assert.equal(outcomes.filter((item) => item.ok).length, 5);
    assert.ok(outcomes.filter((item) => !item.ok).every((item) => /stock/i.test(item.error)));
    assert.equal(db.prepare('SELECT stock FROM products WHERE sku = ?').get('coffee').stock, 0);
    assert.equal(db.prepare('SELECT count(*) AS n FROM orders').get().n, 5);
    assert.equal(db.prepare('SELECT count(*) AS n FROM order_outbox').get().n, 5);
  } finally { db.close(); }
});

import { parentPort, workerData } from 'node:worker_threads';
import { DatabaseSync } from 'node:sqlite';
import { createCheckoutService } from '../../src/checkout.mjs';
const db = new DatabaseSync(workerData.path);
try {
  const result = await createCheckoutService(db)(workerData.request);
  parentPort.postMessage({ ok: true, result });
} catch (error) {
  parentPort.postMessage({ ok: false, error: error.message });
} finally { db.close(); }
